import { useState, useRef } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import { CROPS_ALL } from "../constants/crops";
import { DISEASE_TEMPLATES, SHOPS_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Btn from "../components/ui/Btn";
import LeafCanvas from '../components/ui/LeafModel';

// --- (CROP_DISEASES and CROP_VISUAL_CLUES objects stay here) ---
const CROP_DISEASES = {
  Tomato: ["Early Blight","Late Blight","Yellow Leaf Curl Virus","Mosaic Virus","Target Spot","Leaf Mold","Septoria Leaf Spot","Healthy"],
  Rice: ["Blast Disease","Brown Spot","Sheath Blight","Sheath Rot","Bacterial Leaf Streak","Rice Tungro Virus","False Smut","Healthy"],
  Wheat: ["Yellow Rust","Brown Rust","Alternaria Leaf Blight","Loose Smut","Powdery Mildew","Wheat Blast","Foot Rot","Healthy"],
  Maize: ["Turcicum Leaf Blight","Gray Leaf Spot","Bacterial Stalk Rot","Fusarium Rot","Common Smut","Brown Spot","Maize Dwarf Mosaic","Healthy"],
  Potato: ["Late Blight","Early Blight","Black Scurf","Fusarium Dry Rot","Verticillium Wilt","Common Scab","Potato Virus Y","Healthy"],
  Banana: ["Sigatoka Leaf Spot","Panama Disease","Black Sigatoka","Banana Bunchy Top","Bract Mosaic Virus","Anthracnose","Erwinia Rot","Healthy"],
  Sugarcane: ["Red Rot","Whip Smut","Pokkah Boeng","Pineapple Disease","Gummosis","Grassy Shoot","Mosaic Virus","Healthy"],
  Okra: ["Yellow Vein Mosaic Virus","Enation Leaf Curl","Damping-off","Charcoal Rot","Anthracnose","Cercospora Leaf Spot","Fusarium Wilt","Healthy"],
  Brinjal: ["Bacterial Wilt","Shoot and Fruit Borer","Phomopsis Blight","Cercospora Leaf Spot","Damping-off","Fruit Rot","Little Leaf of Brinjal","Healthy"],
  Cotton: ["Bacterial Blight","Cotton Leaf Curl","Fusarium Wilt","Verticillium Wilt","Areolate Mildew","Root-knot Nematode","Seedling Disease Complex","Healthy"],
  Onion: ["Purple Blotch","Downy Mildew","Twister Disease","White Rot","Pink Root","Bacterial Soft Rot","Onion Yellow Dwarf","Healthy"],
  Groundnut: ["Tikka Leaf Spot","Groundnut Rust","Web Blotch","Bud Necrosis","Rosette Disease","Collar Rot","Stem Rot","Healthy"],
  Turmeric: ["Rhizome Rot","Leaf Blotch","Leaf Spot","Dry Rot","Bacterial Wilt","Leaf Blight","Root-Knot Nematodes","Healthy"],
  Mango: ["Mango Anthracnose","Powdery Mildew","Mango Malformation","Die-back","Bacterial Canker","Sooty Mould","Red Rust","Healthy"],
  Coconut: ["Bud Rot","Tanjore Wilt","Stem Bleeding","Root Wilt","Leaf Rot","Leaf Blight","Healthy"],
  Ragi: ["Ragi Blast","Seedling Blight","Foot Rot","Downy Mildew","Smut","Mosaic Virus","Healthy"],
};

const CROP_VISUAL_CLUES = {
  Tomato: "Look for: brown rings on leaves (Early Blight), dark water-soaked patches (Late Blight), yellow leaf curling (TYLCV), mosaic patterns.",
  Rice: "Look for: diamond-shaped grey spots (Blast), small brown oval spots (Brown Spot), neck rot on panicle, orange discoloration on plant.",
  Wheat: "Look for: yellow/orange powder in stripes (Yellow Rust), orange pustules scattered (Brown Rust), white powdery coating, bleached ears (Blast).",
  Maize: "Look for: long cigar-shaped tan lesions (Turcicum Blight), rectangular grey spots (Gray Leaf Spot), black powdery galls (Common Smut), soft stalk base.",
  Potato: "Look for: dark water-soaked patches with white fuzzy undersides (Late Blight), concentric brown rings (Early Blight), black crusty scabs on tuber.",
  Banana: "Look for: yellow streaks turning brown oval spots (Sigatoka), yellowing of outer leaves collar (Panama Wilt), morse-code streaks on veins (BBTV).",
  Sugarcane: "Look for: red internal stalk tissue with white patches and alcoholic smell (Red Rot), black whip from top (Smut), twisted chlorotic young leaves (Pokkah Boeng).",
  Okra: "Look for: bright yellow vein network (YVMV), downward leaf curl with enations below (Enation Curl), dark stem base (Charcoal Rot).",
  Brinjal: "Look for: wilting with green leaves (Bacterial Wilt), entry holes in shoots/fruits (Fruit Borer), brown sunken lesions on fruits (Phomopsis).",
  Cotton: "Look for: angular water-soaked leaf spots (Bacterial Blight), upward curling with vein thickening (Leaf Curl Virus), white powdery on leaf underside (Areolate Mildew).",
  Onion: "Look for: purple-brown spots with yellow halo (Purple Blotch), violet-grey fuzzy growth (Downy Mildew), twisting/curling of leaves (Twister), white fluffy base (White Rot).",
  Groundnut: "Look for: brown spots with yellow halo (Tikka Early), dark spots no halo (Tikka Late), orange rust pustules on leaf underside, black collar near soil.",
  Turmeric: "Look for: yellowing and foul-smelling rhizome rot (Soft Rot), brown-grey leaf blotches, sudden wilting (Bacterial Wilt).",
  Mango: "Look for: black sunken lesions on leaves/fruit (Anthracnose), white powdery coating on flowers (Powdery Mildew), malformed bunchy flower panicles, twig dieback.",
  Coconut: "Look for: rotting spindle leaf with foul smell (Bud Rot), reddish-brown bleeding at trunk base (Stem Bleeding/Tanjore Wilt), flaccid yellowing leaflets (Root Wilt).",
  Ragi: "Look for: grey spindle spots on leaves (Blast), brown neck causing ear to break (Neck Blast), stunted bushy yellow plant (Downy Mildew), grain replaced by black spores (Smut).",
};

const getFallback = (crop, diseaseName) => {
  if (diseaseName && DISEASE_TEMPLATES[diseaseName]) return DISEASE_TEMPLATES[diseaseName];
  const cropKey = Object.keys(DISEASE_TEMPLATES).find(k => k.toLowerCase() === crop.toLowerCase());
  return cropKey ? DISEASE_TEMPLATES[cropKey] : Object.values(DISEASE_TEMPLATES)[0];
};

// ─── MAIN COMPONENT ───────────────────────────────────────────────────────
export default function DiseaseDetection({ user }) {
  const [crop, setCrop] = useState(user.crops?.[0] || "Tomato");
  const [step, setStep] = useState("upload");
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const fileRef = useRef(null);

  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      setImagePreview(ev.target.result);
      analyzeImage(ev.target.result.split(",")[1], file.type || "image/jpeg");
    };
    reader.readAsDataURL(file);
  };

  const analyzeImage = async (base64, mimeType = "image/jpeg") => {
    setStep("analyzing"); setProgress(0);
    const interval = setInterval(() => setProgress(p => {
      if (p >= 88) { clearInterval(interval); return 88; }
      return p + 3;
    }), 100);

    const diseaseList = (CROP_DISEASES[crop] || []).join(", ");
    const visualClues = CROP_VISUAL_CLUES[crop] || "";

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": process.env.REACT_APP_ANTHROPIC_API_KEY,
          "anthropic-dangerous-direct-browser-access": "true",
        },
        body: JSON.stringify({
          model: "claude-3-5-sonnet-20240620",
          max_tokens: 1200,
          messages: [{
            role: "user",
            content: [
              { type: "image", source: { type: "base64", media_type: mimeType, data: base64 } },
              { type: "text", text: `AI plant pathologist prompt... ${visualClues} ... ${diseaseList}` }
            ]
          }]
        })
      });

      const d = await res.json();
      clearInterval(interval); setProgress(100);
      const raw = d.content?.[0]?.text || "{}";
      const parsed = JSON.parse(raw.replace(/```json|```/g, "").trim());
      const offline = getFallback(crop, parsed.disease);
      setResult({ ...parsed, ...offline });
      setTimeout(() => setStep("result"), 400);
    } catch (err) {
      clearInterval(interval);
      setResult(getFallback(crop, null));
      setTimeout(() => setStep("result"), 400);
    }
  };

  const simulateAnalyze = () => {
    setStep("analyzing"); setProgress(0);
    const t = setInterval(() => setProgress(p => {
      if (p >= 100) {
        clearInterval(t);
        setResult(getFallback(crop, null));
        setTimeout(() => setStep("result"), 200);
      }
      return p + 4;
    }), 80);
  };

  const sevColor = { High: C.red, Medium: C.orange, Low: C.bg2, Healthy: C.bg2, Critical: C.red };

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>🔬 Crop Disease Detection</h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 18px" }}>AI Vision • 3D Health Inspection</p>

      {step === "upload" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18 }}>
          <div>
            <Card style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 9 }}>1. Select Your Crop</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 6 }}>
                {CROPS_ALL.slice(0, 16).map(c => (
                  <button key={c} onClick={() => setCrop(c)}
                    style={{ padding: "7px 4px", borderRadius: 7, fontSize: 12, cursor: "pointer",
                      border: `1.5px solid ${crop === c ? C.bg2 : C.border}`,
                      background: crop === c ? C.pale : C.white, color: crop === c ? C.bg2 : C.text }}>{c}</button>
                ))}
              </div>
            </Card>

            <input ref={fileRef} type="file" accept="image/*" onChange={handleFile} style={{ display: "none" }} />
            <div onClick={() => fileRef.current?.click()}
              style={{ background: C.white, borderRadius: 12, padding: "28px 20px",
                border: `2px dashed ${C.border}`, textAlign: "center", cursor: "pointer" }}>
              <div style={{ fontSize: 42, marginBottom: 8 }}>📸</div>
              <Btn onClick={e => { e.stopPropagation(); fileRef.current?.click(); }}>📷 Scan Plant Photo</Btn>
            </div>
            <div style={{ textAlign: "center", marginTop: 10 }}>
               <button onClick={simulateAnalyze} style={{ fontSize: 12, color: C.bg2, background: "none", border: "none", cursor: "pointer" }}>Use demo image instead</button>
            </div>
          </div>

          <Card>
            <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>📖 Why use 3D Inspection?</div>
            <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.6 }}>
               Our system doesn't just tell you the disease. It provides a **Digital Twin** (3D Model) of your crop to show exactly where fungus spores settle and how to target your spray.
            </div>
            <div style={{ marginTop: 20, opacity: 0.6 }}>
               <LeafCanvas />
            </div>
          </Card>
        </div>
      )}

      {step === "analyzing" && (
        <Card style={{ textAlign: "center", padding: "60px 40px" }}>
          <div style={{ fontSize: 17, fontWeight: 500, color: C.text, marginBottom: 20 }}>Claude AI Vision inspecting {crop}...</div>
          <div style={{ height: 8, background: C.border, borderRadius: 4, overflow: "hidden", maxWidth: 320, margin: "0 auto" }}>
            <div style={{ height: "100%", width: `${progress}%`, background: C.bg2, transition: "width 0.1s" }} />
          </div>
        </Card>
      )}

      {step === "result" && result && (
        <div style={{ display: "grid", gridTemplateColumns: "1.2fr 0.8fr", gap: 14 }}>
          {/* Left: Detailed AI Results */}
          <Card style={{ border: `1.5px solid ${sevColor[result.severity] || C.border}` }}>
             <Badge color={sevColor[result.severity]} bg={C.pale}>{result.severity} Risk</Badge>
             <h2 style={{ fontSize: 22, fontWeight: 700, margin: "10px 0" }}>{result.disease}</h2>
             <div style={{ background: C.pale, padding: 12, borderRadius: 8, fontSize: 13, marginBottom: 15 }}>
                🌿 <b>Summary:</b> {result.tamil_summary}
             </div>
             <div style={{ fontSize: 13, color: C.text }}>
                <b>Treatment:</b>
                {(result.treatment || []).map((t, i) => <div key={i} style={{ marginTop: 5 }}>• {t}</div>)}
             </div>
             <div style={{ marginTop: 20 }}>
               <Btn onClick={() => setStep("upload")}>Scan Another</Btn>
             </div>
          </Card>

          {/* Right: 3D Visualizer */}
          <div style={{ background: "#fff", borderRadius: 16, padding: 10, border: `1px solid ${C.border}` }}>
             <h3 style={{ fontSize: 12, fontWeight: 700, color: C.muted, textAlign: "center", marginBottom: 10 }}>3D HEALTH MODEL</h3>
             <LeafCanvas />
          </div>
        </div>
      )}
    </div>
  );
}
